<div tabindex="0" role="region" aria-label="Scrollbar CSS variables" class="overflow-x-auto rounded-xl border border-slate-300 focus-visible:outline-2 focus-visible:outline-offset-2 dark:border-slate-600">
    <table class="w-full min-w-[48rem] text-left text-sm">
        <caption class="sr-only">Scrollbar variables and theme defaults</caption>
        <thead class="bg-slate-100 dark:bg-slate-900"><tr><th scope="col" class="px-4 py-3">Variable</th><th scope="col" class="px-4 py-3">Light</th><th scope="col" class="px-4 py-3">Dark</th></tr></thead>
        <tbody class="divide-y divide-slate-300 dark:divide-slate-600">
            <tr><th scope="row" class="whitespace-nowrap px-4 py-3"><x-sirius::code>--sir-scrollbar-size</x-sirius::code></th><td class="px-4 py-3"><x-sirius::code>0.5rem</x-sirius::code></td><td class="px-4 py-3"><x-sirius::code>0.5rem</x-sirius::code></td></tr>
            <tr><th scope="row" class="whitespace-nowrap px-4 py-3"><x-sirius::code>--sir-scrollbar-track</x-sirius::code></th><td colspan="2" class="px-4 py-3"><x-sirius::code>color-mix(in oklch, var(--sir-color-border), var(--sir-color-surface) 80%)</x-sirius::code></td></tr>
            <tr><th scope="row" class="whitespace-nowrap px-4 py-3"><x-sirius::code>--sir-scrollbar-thumb</x-sirius::code></th><td class="px-4 py-3"><x-sirius::code>var(--color-slate-400)</x-sirius::code></td><td class="px-4 py-3"><x-sirius::code>var(--color-slate-500)</x-sirius::code></td></tr>
            <tr><th scope="row" class="whitespace-nowrap px-4 py-3"><x-sirius::code>--sir-scrollbar-thumb-hover</x-sirius::code></th><td class="px-4 py-3"><x-sirius::code>var(--color-slate-500)</x-sirius::code></td><td class="px-4 py-3"><x-sirius::code>var(--color-slate-400)</x-sirius::code></td></tr>
        </tbody>
    </table>
</div>
